globalThis.identificationPhotos = (globalThis.identificationPhotos ?? []).concat([{"name":"Cryptopleura lobulifera","taxon":"Cryptopleura lobulifera","kind":"Original anatomy illustration","source":"https://file.iflora.cn/fastdfs/group2/M00/64/C8/wKhnol2BDwyAMLtWALy9LE5ARr0361.pdf","credit":"Anatomy reference, Dawson, plate 46 figure 4","cue":"Look for short, widely spreading blade divisions with crisp or ruffled edges and a visible midrib on lower parts of the blade. Similar Cryptopleura can require microscopic examination.","image":""},{"name":"Mazzaella rosea","taxon":"Mazzaella rosea","source":"https://symbiota.birdmap.africa/collections/individual/index.php?occid=264540","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","credit":"Bolus Herbarium, University of Cape Town, BOL0262411","cue":"Pressed California specimen, cataloged under the older name Rhodoglossum roseum. The broad blade is visible, but drying alters color and shape. Blade appearance alone is insufficient to confirm the species.","image":""},{"name":"Crustose coralline algae","taxon":"Spongites yendoi","photo":30390721,"observation":19725796,"license":"cc-by","credit":"(c) Javier, some rights reserved (CC BY)","image":"","directoryTaxon":"Coralline red algae","cue":"Example: Spongites yendoi. The pink crust lies flat across the rock in the foreground. Shape distinguishes the growth form; several species make similar crusts.","cropped":true}]);
